  const runsKey = workflowId === null ? null : `runs:${projectId}/${workflowId}`
  const { state: firstPage, reload: reloadRuns } = useResource(runsKey, loadRuns, refreshToken)
  const scope = runId === null ? null : { projectId: projectId!, workflowId: workflowId!, runId }
  const loadDetail = useCallback((signal: AbortSignal) => fetchRunDetail(scope!, signal), [scope?.projectId, scope?.workflowId, scope?.runId]) // eslint-disable-line react-hooks/exhaustive-deps
