1	/**
2	 * Pure graph model: builds a containment tree from the /api/entries listing (the configured locations plus a
3	 * flat entry list) and derives what is visible for a given expansion state. No DOM or layout concerns live here.
4	 *
5	 * Identity is (source, locationId, relativePath). Pi/Claude and the configured locations are virtual
6	 * navigation boundaries: every real file or directory belongs to exactly one location, and the same relative
7	 * path in two locations is two different things.
8	 */
9	
10	export type Source = 'Pi' | 'Claude'
11	export const SOURCES: readonly Source[] = ['Pi', 'Claude']
12	export type Category = 'personal' | 'package' | 'plugin' | 'project'
13	export type LocationStatus = 'available' | 'unavailable'
14	/** One configured filesystem location as the API reports it: never an absolute path. */
15	export type Location = { id: string; source: Source; label: string; category: Category; status: LocationStatus; error: string | null }
16	export type EntryKind = 'directory' | 'file'
17	export type Entry = { source: Source; locationId: string; path: string; kind: EntryKind }
18	export type Listing = { locations: Location[]; entries: Entry[] }
19	export type NodeKind = 'source' | 'location' | 'directory' | 'file'
20	
21	/** A source root (locationId null), a location root (path '') or a directory inside a location. */
22	export type FolderRef = { source: Source; locationId: string | null; path: string }
23	
24	/** A Markdown file identified by source, location and nonempty location-relative path. Filename alone is never enough. */
25	export type FileRef = { source: Source; locationId: string; path: string }
26	
27	export type LocationKey = { source: Source; locationId: string }
28	
29	export type GraphNode = {
30	  id: string
31	  source: Source
32	  locationId: string | null
33	  path: string
34	  name: string
35	  kind: NodeKind
36	  parentId: string | null
37	  depth: number
38	  /** Location nodes carry their configured metadata and availability. */
39	  location?: Location
40	}
41	
42	export type GraphEdge = { id: string; parentId: string; childId: string }
43	
44	export type TreeIndex = {
45	  nodes: Map<string, GraphNode>
46	  /** Immediate children in display order: locations in configured order; directories first, then files, each alphabetical. */
47	  children: Map<string, GraphNode[]>
48	  /** Configured locations keyed by their node id (`<source>/<locationId>`). */
49	  locations: Map<string, Location>
50	}
51	
52	export type ChildCounts = { locations: number; directories: number; files: number }
53	
54	/** Matches the server's location id contract; anything else in a URL is malformed rather than looked up. */
55	export const LOCATION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/
56	
57	export function isSource(value: string): value is Source {
58	  return value === 'Pi' || value === 'Claude'
59	}
60	
61	export function isLocationId(value: string): boolean {
62	  return LOCATION_ID_PATTERN.test(value)
63	}
64	
65	export function nodeId(source: Source, locationId: string | null, path: string): string {
66	  if (locationId === null) return source
67	  return path ? `${source}/${locationId}/${path}` : `${source}/${locationId}`
68	}
69	
70	export function refId(ref: FolderRef): string {
71	  return nodeId(ref.source, ref.locationId, ref.path)
72	}
73	
74	export function sameRef(a: FolderRef | null, b: FolderRef | null): boolean {
75	  return a === b || (a !== null && b !== null && a.source === b.source && a.locationId === b.locationId && a.path === b.path)
76	}
77	
78	export function sameFileRef(a: FileRef | null, b: FileRef | null): boolean {
79	  return sameRef(a, b)
80	}
81	
82	/** The folder that contains a file: the location root for top-level files. */
83	export function parentFolderOf(ref: FileRef): FolderRef {
84	  return { source: ref.source, locationId: ref.locationId, path: parentPath(ref.path) }
85	}
86	
87	function baseName(path: string): string {
88	  return path.slice(path.lastIndexOf('/') + 1)
89	}
90	
91	function parentPath(path: string): string {
92	  const index = path.lastIndexOf('/')
93	  return index === -1 ? '' : path.slice(0, index)
94	}
95	
96	const collator = new Intl.Collator('en', { numeric: true, sensitivity: 'base' })
97	
98	const KIND_ORDER: Record<NodeKind, number> = { source: 0, location: 1, directory: 2, file: 3 }
99	
100	function compareNodes(a: GraphNode, b: GraphNode): number {
101	  if (a.kind !== b.kind) return KIND_ORDER[a.kind] - KIND_ORDER[b.kind]
102	  // Locations keep their configured order (the sort is stable).
103	  if (a.kind === 'location') return 0
104	  return collator.compare(a.name, b.name) || (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)
105	}
106	
107	/**
108	 * Builds the containment index. Location nodes come from the configured list, in its order, whether or not
109	 * they are available; entries naming an unconfigured location are dropped rather than inventing one.
110	 * Directory parents are created implicitly if the listing omits them.
111	 */
112	export function buildIndex(listing: Listing): TreeIndex {
113	  const nodes = new Map<string, GraphNode>()
114	  const locations = new Map<string, Location>()
115	  for (const source of SOURCES) {
116	    nodes.set(source, { id: source, source, locationId: null, path: '', name: source, kind: 'source', parentId: null, depth: 0 })
117	  }
118	  for (const location of listing.locations) {
119	    if (!isSource(location.source) || typeof location.id !== 'string' || !isLocationId(location.id)) continue
120	    const id = nodeId(location.source, location.id, '')
121	    if (nodes.has(id)) continue
122	    nodes.set(id, { id, source: location.source, locationId: location.id, path: '', name: location.label, kind: 'location', parentId: location.source, depth: 1, location })
123	    locations.set(id, location)
124	  }
125	  function ensure(source: Source, locationId: string, path: string, kind: NodeKind): GraphNode {
126	    const id = nodeId(source, locationId, path)
127	    const existing = nodes.get(id)
128	    if (existing) return existing
129	    const parent = path.includes('/') ? ensure(source, locationId, parentPath(path), 'directory') : nodes.get(nodeId(source, locationId, ''))!
130	    const node: GraphNode = { id, source, locationId, path, name: baseName(path), kind, parentId: parent.id, depth: parent.depth + 1 }
131	    nodes.set(id, node)
132	    return node
133	  }
134	  for (const entry of listing.entries) {
135	    if (!isSource(entry.source) || typeof entry.locationId !== 'string' || !entry.path) continue
136	    if (entry.path.split('/').some(segment => segment === '' || segment === '.' || segment === '..')) continue
137	    const location = locations.get(nodeId(entry.source, entry.locationId, ''))
138	    if (!location || location.status !== 'available') continue
139	    ensure(entry.source, entry.locationId, entry.path, entry.kind === 'directory' ? 'directory' : 'file')
140	  }
141	  const children = new Map<string, GraphNode[]>()
142	  for (const node of nodes.values()) {
143	    if (node.parentId === null) continue
144	    const siblings = children.get(node.parentId) ?? []
145	    siblings.push(node)
146	    children.set(node.parentId, siblings)
147	  }
148	  for (const siblings of children.values()) siblings.sort(compareNodes)
149	  return { nodes, children, locations }
150	}
151	
152	/** The configured location for a key, only when it belongs to that source. */
153	export function locationOf(index: TreeIndex, key: LocationKey): Location | undefined {
154	  return index.locations.get(nodeId(key.source, key.locationId, ''))
155	}
156	
157	export function childrenOf(index: TreeIndex, id: string): GraphNode[] {
158	  return index.children.get(id) ?? []
159	}
160	
161	export function childCounts(index: TreeIndex, id: string): ChildCounts {
162	  const counts = { locations: 0, directories: 0, files: 0 }
163	  for (const child of childrenOf(index, id)) {
164	    if (child.kind === 'file') counts.files += 1
165	    else if (child.kind === 'location') counts.locations += 1
166	    else counts.directories += 1
167	  }
168	  return counts
169	}
